  'View last report': '查看最近报告',
  'The last report this server sent to Dagu Console. The heartbeat secret is hidden.':
    '此服务器最近发送到 Dagu Console 的报告。心跳密钥已隐藏。',
  'Could not change what this server reports.': '无法更改此服务器报告的内容。',
