const chinese = {
  ...workspaceMessages['zh-CN'],
  ...baseChinese,
} as const satisfies Record<StaticMessage, string>;

const japanese = {
  ...workspaceMessages.ja,
  ...baseJapanese,
} as const satisfies Record<StaticMessage, string>;

export const baseStaticMessages = {
  en: baseEnglish,
  'zh-CN': baseChinese,
  ja: baseJapanese,
} satisfies Record<Locale, Record<BaseStaticMessage, string>>;

export const staticMessages = {
  en: english,
  'zh-CN': chinese,
  ja: japanese,
} satisfies Record<Locale, Record<StaticMessage, string>>;

export function translateStatic(
  locale: Locale,
  source: string,
  values?: StaticTranslationValues
): string {
  const catalog = staticMessages[locale];
  const message =
    locale !== 'en' && Object.prototype.hasOwnProperty.call(catalog, source)
      ? catalog[source as StaticMessage]
      : source;
  if (!values) {
    return message;
  }

  return message.replace(/\{(\w+)\}/g, (placeholder, name: string) => {
    const value = values[name];
    return value === undefined ? placeholder : String(value);
  });
}
